def transform(grid):
    from collections import deque

    rows = len(grid)
    cols = len(grid[0])

    visited = [[False] * cols for _ in range(rows)]
    result = [[0] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c]:
                # Find all 4-connected cells with the same color
                component_cells = []
                color = grid[r][c]
                queue = deque([(r, c)])
                visited[r][c] = True

                while queue:
                    cr, cc = queue.popleft()
                    component_cells.append((cr, cc))

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if (0 <= nr < rows and 0 <= nc < cols and 
                            not visited[nr][nc] and grid[nr][nc] == color):
                            visited[nr][nc] = True
                            queue.append((nr, nc))

                # Determine if this connected component touches any grid boundary
                touches_edge = any(
                    r_pos == 0 or r_pos == rows - 1 or 
                    c_pos == 0 or c_pos == cols - 1 
                    for r_pos, c_pos in component_cells
                )

                # Fill component cells in result: keep original color if touches edge, otherwise 3
                for tr, tc in component_cells:
                    if touches_edge:
                        result[tr][tc] = color
                    else:
                        result[tr][tc] = 3

    return result
