    # Find the marker color (minority color, less frequent than most common)
    if len(color_counts) == 1:
        return result

    sorted_counts = sorted(color_counts.items(), key=lambda x: x[1])
    marker_color = sorted_counts[0][0]  # Least frequent

    # Fill horizontally between consecutive markers for each row
    for r in range(rows):
        positions = sorted([c for c in range(cols) if grid[r][c] == marker_color])
        for i in range(1, len(positions)):
